[Expression]:
COUNTROWS (
    SUMMARIZE (
        FILTER ( 'Metrics-Day Count', 'Metrics-Day Count'[wrk_day_ind] = 1 ),
        'Metrics-Day Count'[day_id]
    )
)

COUNTROWS(
    FILTER(
        ADDCOLUMNS(
            SUMMARIZE(
                FILTER(
                    'Metrics-Actuals-Vol',
                    RELATED('Transaction Type'[trx_type_cd]) <> "2" // Remove Estimates
                ),
                'Ship To'[ship_to_loc_id]
            ),

            "Summarized Physical Cases AC for Covered Outlets", [Physical Cases AC]
        ),
        [Summarized Physical Cases AC for Covered Outlets] > 0
    )
)

COUNTROWS (
    FILTER (
        SUMMARIZE (
            'Metrics-Actuals-Vol',
            'Period'[day_id],
            "Summarized Physical Cases AC for Days of purchase", [Physical Cases AC]
        ),
        [Summarized Physical Cases AC for Days of purchase] > 0
    )
)
